# Event titles and texts: (EN title, EN text, RU title, RU text). Ids match China1928_Events.lua.
# Neutral, factual wording for every side; effects are stated at the end of each text.
EVENTS = {
 # --- the National Government
 'NAN_CHAIRMAN': ("Chairman of the National Government", "On the anniversary of the Wuchang rising the Organic Law of the National Government takes effect in Nanjing: five branches of government, the Yuan, under the tutelage of the Kuomintang, and Chiang Kai-shek as Chairman of the National Government. The National Government receives 300 gold.",
                  "Председатель Национального правительства", "В годовщину Учанского восстания в Нанкине вступает в силу Органический закон Национального правительства: пять ветвей власти, юаней, под опекой Гоминьдана, и Чан Кайши во главе как председатель Национального правительства. Национальное правительство получает 300 золота."),
 'NAN_DISBANDMENT': ("The Disbandment Conference", "The National Reorganisation and Disbandment Conference opens in Nanjing. The government proposes to cut the two million men under arms to eight hundred thousand and to bring every army under its own budget; the group armies agree in principle and keep their divisions in practice. The National Government receives 400 gold; the Guominjun, Shanxi and Guangxi each pay 150.",
                     "Конференция по сокращению армий", "В Нанкине открывается Конференция по реорганизации и сокращению армий. Правительство предлагает сократить два миллиона человек под ружьём до восьмисот тысяч и перевести все армии на свой бюджет; армейские группы соглашаются в принципе и сохраняют свои дивизии на деле. Национальное правительство получает 400 золота; Гоминьцзюнь, Шаньси и Гуанси платят по 150."),
 'NAN_GUANGXI_WAR': ("The Chiang-Guangxi War", "After the Wuhan Political Council drove the Hunan governor out of Changsha without Nanjing's consent, the National Government orders a punitive expedition against Li Zongren, Bai Chongxi and Li Jishen. In Hebei, Bai Chongxi's troops at Tangshan turn against him and he escapes by sea. The National Government declares war on Guangxi and raises three Central Army divisions and a battery; Guangxi loses its units around Tangshan.",
                     "Война Чана с Гуанси", "После того как Уханьский политический совет без согласия Нанкина изгнал из Чанши губернатора Хунани, Национальное правительство объявляет карательный поход против Ли Цзунжэня, Бай Чунси и Ли Цзишэня. В Хэбэе войска Бай Чунси в Таншане выходят из повиновения, и он бежит морем. Национальное правительство объявляет войну Гуанси и получает три дивизии Центральной армии и батарею; Гуанси теряет свои отряды под Таншанем."),
 'NAN_WUHAN': ("The fall of Wuhan", "Guangxi divisions in Hubei go over to Nanjing, and the rest of the Fourth Group Army falls back up the Yangtze; Nanjing's troops enter Wuhan without a battle. The National Government receives two divisions; Guangxi loses 300 gold and two units around Hankou.",
               "Падение Уханя", "Гуансийские дивизии в Хубэе переходят на сторону Нанкина, остальная Четвёртая армейская группа отходит вверх по Янцзы; нанкинские войска входят в Ухань без боя. Национальное правительство получает две дивизии; Гуанси теряет 300 золота и два отряда под Ханькоу."),
 'NAN_CENTRAL_PLAINS': ("The Central Plains War", "Chiang Kai-shek orders the general offensive against the coalition of Yan Xishan, Feng Yuxiang and the Guangxi clique. Along the Longhai and the Tianjin-Pukou railways more than a million men take the field in the largest war China has seen since the Taiping rebellion. The National Government raises four Central Army divisions, two batteries and an air squadron at Xuzhou.",
                        "Центральная равнинная война", "Чан Кайши отдаёт приказ о генеральном наступлении против коалиции Янь Сишаня, Фэн Юйсяна и гуансийской клики. Вдоль дорог Лунхай и Тяньцзинь-Пукоу в поле выходит больше миллиона человек: крупнейшая война в Китае со времён тайпинов. Национальное правительство получает в Сюйчжоу четыре дивизии Центральной армии, две батареи и авиаэскадрилью."),
 'NAN_PLAINS_END': ("The end of the Central Plains War", "With the Northeast Army in Beiping and their armies beaten along the Longhai, Yan Xishan and Feng Yuxiang announce their retirement. Yan leaves for Dalian; Feng's Guominjun breaks up, its divisions taken over by Nanjing, Shanxi and Zhang Xueliang. The National Government makes peace with the Guominjun and Shanxi and receives 500 gold; the Guominjun loses five units, Shanxi 400 gold.",
                    "Конец Центральной равнинной войны", "Когда Северо-Восточная армия уже в Бэйпине, а их армии разбиты на Лунхае, Янь Сишань и Фэн Юйсян объявляют об уходе от дел. Янь уезжает в Далянь; Гоминьцзюнь распадается, его дивизии разбирают Нанкин, Шаньси и Чжан Сюэлян. Национальное правительство заключает мир с Гоминьцзюнем и Шаньси и получает 500 золота; Гоминьцзюнь теряет пять отрядов, Шаньси 400 золота."),
 'NAN_ENCIRCLE_1': ("The first encirclement campaign", "Lu Diping, governor of Jiangxi, orders the first offensive against the Red Army's base in southern Jiangxi; in December the converging columns march into the hills between Ji'an and Ningdu. Three Bandit Suppression divisions muster at Ji'an.",
                    "Первый поход окружения", "Губернатор Цзянси Лу Дипин отдаёт приказ о первом наступлении на базу Красной армии на юге Цзянси; в декабре сходящиеся колонны входят в горы между Цзиань и Нинду. В Цзиань собираются три дивизии по подавлению бандитов."),
 'NAN_ENCIRCLE_2': ("The second encirclement campaign", "He Yingqin brings two hundred thousand men against the soviet base in southern Jiangxi, advancing slowly from Ji'an, Nanfeng and the Fujian border. Four Bandit Suppression divisions and a battery muster at Ji'an.",
                    "Второй поход окружения", "Хэ Инцинь ведёт двести тысяч человек на советский район юга Цзянси, медленно наступая от Цзиань, Наньфэна и с границы Фуцзяни. В Цзиань собираются четыре дивизии по подавлению бандитов и батарея."),
 'NAN_ENCIRCLE_3': ("The third encirclement campaign", "Chiang Kai-shek takes command at Nanchang himself and sends the Central Army into southern Jiangxi in a deep thrust meant to find and destroy the Red Army. Four Central Army divisions muster there, two Bandit Suppression divisions at Ji'an.",
                    "Третий поход окружения", "Чан Кайши сам принимает командование в Наньчане и бросает Центральную армию в глубокий прорыв на юг Цзянси, чтобы найти и уничтожить Красную армию. Там же собираются четыре дивизии Центральной армии, в Цзиань две дивизии по подавлению бандитов."),
 'NAN_FLOODS': ("The great flood", "After months of rain the Yangtze, the Huai and the Han burst their dykes. Wuhan stands under water for months, and tens of millions lose their homes and fields across central China. The National Government loses 600 gold, Guangxi 200.",
                "Великое наводнение", "После месяцев дождей Янцзы, Хуайхэ и Ханьшуй прорывают дамбы. Ухань на месяцы уходит под воду, десятки миллионов людей по всему центральному Китаю теряют дома и поля. Национальное правительство теряет 600 золота, Гуанси 200."),
 'NAN_REUNION': ("Reunion", "After the Mukden incident the rival governments in Nanjing and Canton come to terms: Chiang Kai-shek has stepped down, Lin Sen takes office as Chairman of the National Government, and the Canton government dissolves itself. The National Government makes peace with Guangxi and receives 300 gold.",
                 "Воссоединение", "После Мукденского инцидента соперничающие правительства Нанкина и Кантона договариваются: Чан Кайши ушёл в отставку, председателем Национального правительства становится Линь Сэнь, кантонское правительство распускается. Национальное правительство заключает мир с Гуанси и получает 300 золота."),
 'NAN_ENCIRCLE_4': ("The fourth encirclement campaign", "Chen Cheng leads the best divisions of the Central Army against the Jiangxi Soviet from the north. Four Central Army divisions muster at Nanchang.",
                    "Четвёртый поход окружения", "Чэнь Чэн ведёт лучшие дивизии Центральной армии на Цзянсийский советский район с севера. В Наньчане собираются четыре дивизии Центральной армии."),
 'NAN_ENCIRCLE_5': ("The fifth encirclement campaign", "Chiang Kai-shek opens the fifth campaign against the Jiangxi Soviet with new tactics: a slow advance behind lines of stone blockhouses and roads, an economic blockade of the soviet area, and divisions trained by the German advisory mission. Five German-trained divisions, two batteries, two air squadrons and two blockhouse builders muster at Nanchang, and the National Government receives 500 gold.",
                    "Пятый поход окружения", "Чан Кайши открывает пятый поход против Цзянсийского советского района с новой тактикой: медленное наступление за линиями каменных блокгаузов и дорог, экономическая блокада советского района и дивизии, обученные германской военной миссией. В Наньчане собираются пять обученных немцами дивизий, две батареи, две авиаэскадрильи и два отряда строителей блокгаузов; Национальное правительство получает 500 золота."),
 'NAN_NEW_LIFE': ("The New Life Movement", "In Nanchang Chiang Kai-shek launches the New Life Movement, a campaign of discipline, cleanliness and Confucian virtue meant to remake the habits of the nation. The National Government receives 200 gold.",
                  "Движение за новую жизнь", "В Наньчане Чан Кайши объявляет Движение за новую жизнь, кампанию дисциплины, чистоты и конфуцианских добродетелей, призванную переделать привычки нации. Национальное правительство получает 200 золота."),
 'NAN_FABI': ("The currency reform", "China leaves the silver standard. The notes of the government banks become the only legal tender, the fabi, and the silver of the country is called in. The National Government receives 1000 gold.",
              "Денежная реформа", "Китай отказывается от серебряного стандарта. Банкноты государственных банков, фаби, становятся единственным законным платёжным средством, а серебро страны изымается. Национальное правительство получает 1000 золота."),
 'NAN_CANTON': ("Canton returns to Nanjing", "The Liangguang incident ends in Guangdong: Chen Jitang's air force and generals go over to Nanjing, and Chen leaves Canton for Hong Kong. Guangdong comes under the National Government. The National Government takes over the cities of Guangdong.",
                "Кантон возвращается к Нанкину", "Инцидент Лянгуан заканчивается в Гуандуне: авиация и генералы Чэнь Цзитана переходят на сторону Нанкина, и Чэнь уезжает из Кантона в Гонконг. Гуандун переходит под власть Национального правительства. Национальное правительство получает города Гуандуна."),
 'NAN_XIAN_RELEASE': ("Chiang released", "After two weeks of negotiations in Xi'an with Zhang Xueliang, Yang Hucheng and a Communist delegation led by Zhou Enlai, Chiang Kai-shek is released and flies back to Nanjing, with Zhang Xueliang beside him; Zhang is court-martialled and kept under arrest. The civil war with the Communists stops. The National Government makes peace with the Communists; Fengtian loses 500 gold.",
                      "Освобождение Чана", "После двух недель переговоров в Сиани с Чжан Сюэляном, Ян Хучэном и делегацией коммунистов во главе с Чжоу Эньлаем Чан Кайши освобождён и улетает в Нанкин, а с ним Чжан Сюэлян; Чжана судят военным судом и держат под арестом. Гражданская война с коммунистами прекращается. Национальное правительство заключает мир с коммунистами; Фэнтянь теряет 500 золота."),
 'NAN_WEIHAIWEI': ("The rendition of Weihaiwei", "Britain returns the leased territory of Weihaiwei, held since 1898, to China. The National Government takes over Weihaiwei.",
                   "Возвращение Вэйхайвэя", "Великобритания возвращает Китаю арендованную с 1898 года территорию Вэйхайвэй. Национальное правительство получает Вэйхайвэй."),
 'NAN_FUZHOU': ("Fuzhou retaken", "The Central Army takes Fuzhou and the Fujian People's Government collapses; its leaders escape to Hong Kong and the 19th Route Army is broken up. The National Government receives 200 gold; the rebel units around Fuzhou disband.",
                "Фучжоу взят", "Центральная армия берёт Фучжоу, и Фуцзяньское народное правительство рушится; его вожди бегут в Гонконг, 19-я армия расформирована. Национальное правительство получает 200 золота; мятежные отряды под Фучжоу расходятся."),
 'NAN_LEVY': ("Recruits for the Central Army", "A new division of the Central Army is ready in Nanjing.", "Пополнение Центральной армии", "В Нанкине готова новая дивизия Центральной армии."),
 # --- the Guominjun
 'GMJ_FAMINE': ("Famine in the northwest", "Three years without rain have brought famine to Shaanxi and Gansu and spread it to Henan, Shanxi and Suiyuan; millions are starving and the roads fill with refugees and bandits. The Guominjun loses 300 gold; bandits appear in Gansu and Shaanxi.",
                "Голод на северо-западе", "Три года без дождей принесли голод в Шэньси и Ганьсу и распространили его на Хэнань, Шаньси и Суйюань; голодают миллионы, дороги заполнены беженцами и разбойниками. Гоминьцзюнь теряет 300 золота; в Ганьсу и Шэньси появляются разбойники."),
 'GMJ_HAN_FUJU': ("Han Fuju changes sides", "As Feng Yuxiang prepares to break with Nanjing, two of his best generals, Han Fuju and Shi Yousan, declare for Chiang Kai-shek and take their troops with them. The Guominjun loses two units around Luoyang; the National Government receives three divisions.",
                  "Хань Фуцзюй меняет сторону", "Пока Фэн Юйсян готовится порвать с Нанкином, два его лучших генерала, Хань Фуцзюй и Ши Юсань, объявляют о поддержке Чан Кайши и уводят свои войска. Гоминьцзюнь теряет два отряда под Лояном; Национальное правительство получает три дивизии."),
 'GMJ_WAR_1929': ("The Guominjun against Nanjing", "Song Zheyuan and the other generals of the Guominjun publish a telegram denouncing Chiang Kai-shek and march east into western Henan, while Feng Yuxiang himself is held by Yan Xishan in Shanxi. The Guominjun declares war on the National Government and raises three divisions and a cavalry brigade.",
                  "Гоминьцзюнь против Нанкина", "Сун Чжэюань и другие генералы Гоминьцзюня публикуют телеграмму против Чан Кайши и выступают на восток, в западную Хэнань, пока сам Фэн Юйсян находится у Янь Сишаня в Шаньси. Гоминьцзюнь объявляет войну Национальному правительству и получает три дивизии и кавалерийскую бригаду."),
 'GMJ_CENTRAL_PLAINS': ("The Guominjun in the Central Plains", "Feng Yuxiang's armies, the strongest of the coalition, march east along the Longhai railway towards Xuzhou and south down the Beijing-Hankou line. The Guominjun raises four divisions, a battery and a cavalry brigade.",
                        "Гоминьцзюнь на Центральной равнине", "Армии Фэн Юйсяна, самые сильные в коалиции, идут на восток по дороге Лунхай к Сюйчжоу и на юг по линии Пекин-Ханькоу. Гоминьцзюнь получает четыре дивизии, батарею и кавалерийскую бригаду."),
 'GMJ_CHAHAR': ("The Anti-Japanese Allied Army", "At Zhangjiakou Feng Yuxiang founds the Chahar People's Anti-Japanese Allied Army from his old soldiers, local troops and volunteers; in July it retakes Duolun from the Japanese and Manchukuo forces. The Guominjun raises three divisions and a cavalry brigade at Zhangjiakou.",
                 "Антияпонская союзная армия", "В Чжанцзякоу Фэн Юйсян создаёт Чахарскую народную антияпонскую союзную армию из старых солдат, местных войск и добровольцев; в июле она отбивает Долон у японцев и войск Маньчжоу-го. Гоминьцзюнь получает в Чжанцзякоу три дивизии и кавалерийскую бригаду."),
 'GMJ_CHAHAR_END': ("The Allied Army disbanded", "Under pressure from Nanjing and the Japanese, and with its money gone, Feng Yuxiang gives up command of the Anti-Japanese Allied Army and retires to Mount Tai; the army is broken up. The Allied Army's units disband.",
                    "Союзная армия распущена", "Под давлением Нанкина и японцев, без денег, Фэн Юйсян слагает командование Антияпонской союзной армией и удаляется на гору Тайшань; армия расформирована. Отряды Союзной армии расходятся."),
 'GMJ_LEVY': ("Recruits for the Guominjun", "New Guominjun troops are ready.", "Пополнение Гоминьцзюня", "Новые войска Гоминьцзюня готовы."),
 # --- Shanxi
 'SHX_COALITION': ("The coalition against Chiang", "At Taiyuan Yan Xishan is sworn in as commander-in-chief of the armies opposed to Chiang Kai-shek, with Feng Yuxiang and Li Zongren as his deputies. Shanxi and Guangxi declare war on the National Government; Shanxi raises three divisions and a mountain battery.",
                   "Коалиция против Чана", "В Тайюане Янь Сишань принимает присягу как главнокомандующий армиями, выступившими против Чан Кайши; его заместители Фэн Юйсян и Ли Цзунжэнь. Шаньси и Гуанси объявляют войну Национальному правительству; Шаньси получает три дивизии и горную батарею."),
 'SHX_BEIPING_GOVT': ("The Enlarged Conference", "In Beiping the Enlarged Conference of the Kuomintang's opposition factions, with Wang Jingwei, proclaims a rival National Government with Yan Xishan as its chairman. Shanxi receives 400 gold.",
                      "Расширенная конференция", "В Бэйпине Расширенная конференция оппозиционных фракций Гоминьдана с участием Ван Цзинвэя провозглашает соперничающее Национальное правительство с Янь Сишанем во главе. Шаньси получает 400 золота."),
 'SHX_RETURN': ("Yan Xishan returns", "After a year in Dalian, Yan Xishan is back in Taiyuan; Nanjing, facing Japan, names him Taiyuan Pacification Commissioner. Shanxi receives 500 gold.",
                "Возвращение Янь Сишаня", "После года в Даляне Янь Сишань снова в Тайюане; Нанкин перед лицом Японии назначает его тайюаньским уполномоченным по умиротворению. Шаньси получает 500 золота."),
 'SHX_INDUSTRY': ("The Northwest Industrial Company", "Under his Ten-Year Plan Yan Xishan gathers the arsenal and the provincial works into the Northwest Industrial Company, and work begins on the narrow-gauge railway from Datong to the Yellow River. Shanxi receives 600 gold.",
                  "Северо-западная промышленная компания", "По своему десятилетнему плану Янь Сишань объединяет арсенал и провинциальные заводы в Северо-западную промышленную компанию, и начинается строительство узкоколейной дороги от Датуна до Хуанхэ. Шаньси получает 600 золота."),
 'SHX_BAILINGMIAO': ("Bailingmiao", "Fu Zuoyi's troops beat back the attack on eastern Suiyuan and then storm Bailingmiao, the base of the Mongol and puppet forces, in a night attack in the snow. The victory is celebrated across China. Shanxi receives 300 gold, two divisions and a cavalry brigade at Guisui.",
                     "Байлинмяо", "Войска Фу Цзои отбивают наступление на восточный Суйюань, а затем ночной атакой в метель берут Байлинмяо, базу монгольских и марионеточных войск. Победу празднует весь Китай. Шаньси получает 300 золота, две дивизии и кавалерийскую бригаду в Гуйсуе."),
 'SHX_LEVY': ("Recruits for the Shanxi army", "New Shanxi troops are ready in Taiyuan.", "Пополнение шаньсийской армии", "В Тайюане готовы новые шаньсийские войска."),
 # --- Fengtian
 'FT_INTO_THE_PASS': ("The Northeast Army enters the pass", "Zhang Xueliang sends a circular telegram calling for an end to the war and declaring for Nanjing; the Northeast Army marches through Shanhaiguan. Yan Xishan's troops leave Beiping and Tianjin without a fight, and Hebei passes to the Young Marshal. Fengtian receives 800 gold and three divisions and takes over Tianjin and Beiping from Shanxi.",
                      "Северо-Восточная армия входит за Великую стену", "Чжан Сюэлян рассылает телеграмму с призывом прекратить войну и объявляет о поддержке Нанкина; Северо-Восточная армия проходит через Шаньхайгуань. Войска Янь Сишаня без боя оставляют Бэйпин и Тяньцзинь, и Хэбэй переходит к молодому маршалу. Фэнтянь получает 800 золота и три дивизии, а также Тяньцзинь и Бэйпин от Шаньси."),
 'FT_FLAG': ("The Northeast Flag Replacement", "In Mukden and across Manchuria the five-coloured flag comes down and the flag of the Republic goes up: Zhang Xueliang recognises the National Government, which leaves him in charge of the Northeast. Fengtian receives 300 gold and declares friendship with the National Government.",
             "Смена флагов на Северо-Востоке", "В Мукдене и по всей Маньчжурии спускают пятицветный флаг и поднимают флаг Республики: Чжан Сюэлян признаёт Национальное правительство, которое оставляет за ним власть на Северо-Востоке. Фэнтянь получает 300 золота и объявляет о дружбе с Национальным правительством."),
 'FT_YANG_CHANG': ("The Yang-Chang incident", "At a dinner in his residence Zhang Xueliang has his father's chief of staff Yang Yuting and the governor of Heilongjiang Chang Yinhuai shot, ending the old generals' challenge to his authority. Fengtian receives 300 gold.",
                   "Инцидент Ян-Чан", "На ужине в своей резиденции Чжан Сюэлян приказывает расстрелять бывшего начальника штаба своего отца Ян Юйтина и губернатора Хэйлунцзяна Чан Иньхуая; вызов старых генералов его власти окончен. Фэнтянь получает 300 золота."),
 'FT_CER': ("The Chinese Eastern Railway", "Chinese authorities seize the telegraph and the offices of the Chinese Eastern Railway, run jointly with the Soviet Union, and arrest or expel its Soviet managers. Moscow breaks off relations and gathers the Special Far Eastern Army on the frontier.",
            "Китайско-Восточная железная дорога", "Китайские власти захватывают телеграф и управления Китайско-Восточной железной дороги, которой управляли совместно с Советским Союзом, арестовывают или высылают её советских руководителей. Москва разрывает отношения и сосредоточивает на границе Особую Дальневосточную армию."),
 'SOVIET_LAHASUSU': ("Lahasusu", "Ships of the Soviet Amur Flotilla and troops of the Special Far Eastern Army under Vasily Blyukher strike at the mouth of the Songhua, sink the Chinese river flotilla and take Lahasusu. The Soviet Union declares war on Fengtian; units of the Special Far Eastern Army land on the Songhua.",
                     "Лахасусу", "Корабли советской Амурской флотилии и войска Особой Дальневосточной армии Василия Блюхера наносят удар в устье Сунгари, топят китайскую речную флотилию и берут Лахасусу. Советский Союз объявляет войну Фэнтяню; отряды Особой Дальневосточной армии высаживаются на Сунгари."),
 'SOVIET_MANZHOULI': ("Manzhouli and Zhalainuoer", "The Special Far Eastern Army crosses the border in the west, encircles the Chinese troops at Manzhouli and Zhalainuoer and advances on Hailar, with tanks and aircraft against an army that has neither. Soviet infantry, tanks and cavalry cross the border at Manzhouli.",
                      "Маньчжурия и Чжалайнор", "Особая Дальневосточная армия переходит границу на западе, окружает китайские войска у станции Маньчжурия и Чжалайнора и наступает на Хайлар, с танками и самолётами против армии, у которой нет ни того, ни другого. Советская пехота, танки и кавалерия переходят границу у Маньчжурии."),
 'SOVIET_KHABAROVSK': ("The Khabarovsk Protocol", "Fengtian's negotiators sign the Khabarovsk Protocol: the joint Soviet-Chinese management of the Chinese Eastern Railway is restored as before July, and the Soviet troops withdraw. The Soviet Union makes peace with Fengtian; its expeditionary units leave.",
                       "Хабаровский протокол", "Представители Фэнтяня подписывают Хабаровский протокол: совместное советско-китайское управление КВЖД восстанавливается в довоенном виде, советские войска уходят. Советский Союз заключает мир с Фэнтянем; его экспедиционные отряды уходят."),
 'FT_NENJIANG': ("The Nenjiang Bridge", "In Heilongjiang Ma Zhanshan refuses the order not to resist and fights the Kwantung Army at the Nenjiang railway bridge; his stand makes him a national hero. Fengtian raises two divisions and a cavalry brigade at Qiqihar.",
                 "Мост через Нэньцзян", "В Хэйлунцзяне Ма Чжаньшань отказывается выполнять приказ не сопротивляться и даёт бой Квантунской армии у железнодорожного моста через Нэньцзян; его стойкость делает его национальным героем. Фэнтянь получает в Цицикаре две дивизии и кавалерийскую бригаду."),
 'FT_RESIGNATION': ("Zhang Xueliang resigns", "After the loss of Rehe and the fall of Chengde without a battle, Zhang Xueliang takes the blame, resigns his posts and leaves for Europe. Fengtian loses 300 gold.",
                    "Отставка Чжан Сюэляна", "После потери Жэхэ и сдачи Чэндэ без боя Чжан Сюэлян берёт вину на себя, уходит со всех постов и уезжает в Европу. Фэнтянь теряет 300 золота."),
 'FT_RETURN': ("The Young Marshal returns", "Back from Europe and cured of his opium habit, Zhang Xueliang becomes deputy commander of the Henan-Hubei-Anhui Bandit Suppression Headquarters at Wuchang, and his Northeast Army is sent against the Communists. Fengtian receives 500 gold and three divisions.",
               "Возвращение молодого маршала", "Вернувшись из Европы и избавившись от опиумной зависимости, Чжан Сюэлян становится заместителем командующего штабом по подавлению бандитов в провинциях Хэнань, Хубэй и Аньхой в Учане, и его Северо-Восточная армия брошена против коммунистов. Фэнтянь получает 500 золота и три дивизии."),
 'FT_NORTHWEST': ("The Northwest Bandit Suppression Headquarters", "Chiang Kai-shek moves Zhang Xueliang and the Northeast Army to Xi'an to destroy the Red Army that has just reached northern Shaanxi. The exiled soldiers of the Northeast, far from home, have little wish to fight other Chinese. Fengtian raises three divisions and a Great General at Xi'an.",
                  "Северо-западный штаб по подавлению бандитов", "Чан Кайши перебрасывает Чжан Сюэляна и Северо-Восточную армию в Сиань, чтобы уничтожить Красную армию, только что пришедшую на север Шэньси. Изгнанным с родины солдатам Северо-Востока мало хочется воевать с другими китайцами. Фэнтянь получает в Сиани три дивизии и Великого полководца."),
 'FT_XIAN': ("The Xi'an incident", "In the early hours Zhang Xueliang's guards and Yang Hucheng's troops seize Chiang Kai-shek at Huaqing hot springs outside Xi'an. The two generals demand an end to the civil war and a united front against Japan. Fengtian makes peace with the Communists.",
             "Сианьский инцидент", "Ранним утром охрана Чжан Сюэляна и войска Ян Хучэна захватывают Чан Кайши у горячих источников Хуацин под Сианью. Генералы требуют прекратить гражданскую войну и создать единый фронт против Японии. Фэнтянь заключает мир с коммунистами."),
 'FT_LEVY': ("Recruits for the Northeast Army", "New troops of the Northeast Army are ready.", "Пополнение Северо-Восточной армии", "Новые войска Северо-Восточной армии готовы."),
 'FT_VOLUNTEERS': ("Northeast Volunteer Army", "Former soldiers, police, peasants and members of secret societies take up arms against the Japanese in Manchuria.", "Северо-Восточная добровольческая армия", "Бывшие солдаты, полицейские, крестьяне и члены тайных обществ поднимаются против японцев в Маньчжурии."),
 # --- Japan
 'JAPAN_MUKDEN': ("The Mukden incident", "Late at night a small charge explodes on the South Manchuria Railway near Liutiaohu, north of Mukden. Officers of the Kwantung Army, who placed it, blame Chinese soldiers and attack the Beidaying barracks; by morning Mukden and its arsenal and airfield are in Japanese hands. Zhang Xueliang orders his troops not to resist. Japan declares war on Fengtian, and Kwantung Army units appear along the railway at Mukden, Changchun and Andong; Fengtian loses 500 gold.",
                  "Мукденский инцидент", "Поздно ночью на Южно-Маньчжурской железной дороге у Лютяоху, к северу от Мукдена, взрывается небольшой заряд. Заложившие его офицеры Квантунской армии обвиняют китайских солдат и атакуют казармы Бэйдаин; к утру Мукден с арсеналом и аэродромом в руках японцев. Чжан Сюэлян приказывает войскам не сопротивляться. Япония объявляет войну Фэнтяню, отряды Квантунской армии появляются вдоль дороги у Мукдена, Чанчуня и Андуна; Фэнтянь теряет 500 золота."),
 'JAPAN_KOREA_ARMY': ("The Korea Army crosses the Yalu", "Without orders from Tokyo, the Japanese Korea Army crosses the Yalu at Sinuiju to reinforce the Kwantung Army. Japan raises three divisions and an air unit at Pyongyang.",
                      "Корейская армия переходит Ялу", "Без приказа из Токио японская Корейская армия переходит Ялу у Синыйджу на помощь Квантунской армии. Япония получает в Пхеньяне три дивизии и авиаотряд."),
 'JAPAN_JINZHOU': ("Jinzhou", "After weeks of bombing, the Kwantung Army advances on Jinzhou, the seat of Zhang Xueliang's remaining government in Manchuria; the Northeast Army withdraws south of the Great Wall. Kwantung Army units advance on Jinzhou.",
                   "Цзиньчжоу", "После недель бомбардировок Квантунская армия наступает на Цзиньчжоу, где сидело остающееся в Маньчжурии правительство Чжан Сюэляна; Северо-Восточная армия отходит за Великую стену. Отряды Квантунской армии наступают на Цзиньчжоу."),
 'JAPAN_SHANGHAI': ("The Shanghai incident", "After clashes in the International Settlement, Japanese marines attack the Chinese district of Zhabei. The 19th Route Army fights back, and Japan sends a fleet and an expeditionary army; Chiang's Fifth Army joins the defence. Japan declares war on the National Government and lands an army and a fleet at Wusong; the National Government raises the 19th Route Army and the Fifth Army at Shanghai.",
                    "Шанхайский инцидент", "После столкновений в Международном сеттльменте японская морская пехота атакует китайский район Чжабэй. 19-я армия даёт отпор, Япония присылает флот и экспедиционную армию; к обороне присоединяется Пятая армия Чана. Япония объявляет войну Национальному правительству и высаживает армию и флот у Усуна; Национальное правительство получает в Шанхае 19-ю и Пятую армии."),
 'JAPAN_HARBIN': ("Harbin", "The Kwantung Army enters Harbin; Chinese troops in northern Manchuria fall back east along the railway. Kwantung Army units appear near Harbin.",
                  "Харбин", "Квантунская армия входит в Харбин; китайские войска северной Маньчжурии отходят на восток вдоль дороги. Отряды Квантунской армии появляются у Харбина."),
 'JAPAN_MANCHUKUO': ("Manchukuo", "The Kwantung Army proclaims the state of Manchukuo, with the former emperor Puyi as Chief Executive and Changchun, renamed Xinjing, as its capital. The League of Nations sends the Lytton Commission. If Japan holds Changchun, it is renamed Xinjing; Japan raises three units of the Manchukuo army.",
                     "Маньчжоу-го", "Квантунская армия провозглашает государство Маньчжоу-го во главе с бывшим императором Пу И как верховным правителем и со столицей в Чанчуне, переименованном в Синьцзин. Лига Наций посылает комиссию Литтона. Если Чанчунь у Японии, он переименован в Синьцзин; Япония получает три отряда армии Маньчжоу-го."),
 'JAPAN_SHANGHAI_TRUCE': ("The Shanghai ceasefire", "With British, American and French mediation, China and Japan sign the Shanghai Ceasefire Agreement: Shanghai is demilitarised and the Japanese expeditionary army leaves. Japan makes peace with the National Government; the Shanghai expeditionary units leave.",
                          "Шанхайское перемирие", "При посредничестве Британии, США и Франции Китай и Япония подписывают Шанхайское соглашение о прекращении огня: Шанхай демилитаризован, японская экспедиционная армия уходит. Япония заключает мир с Национальным правительством; шанхайские экспедиционные отряды уходят."),
 'JAPAN_SHANHAIGUAN': ("Shanhaiguan", "On New Year's night, Japanese troops attack Shanhaiguan, where the Great Wall meets the sea, and take it in three days. Kwantung Army units appear before Shanhaiguan.",
                       "Шаньхайгуань", "В новогоднюю ночь японские войска атакуют Шаньхайгуань, где Великая стена выходит к морю, и берут его за три дня. Отряды Квантунской армии появляются у Шаньхайгуаня."),
 'JAPAN_REHE': ("The invasion of Rehe", "Japanese and Manchukuo forces invade Rehe. Tang Yulin's army falls apart, and on 4 March a small motorised column enters Chengde unopposed; the fighting moves to the passes of the Great Wall, where Central Army and northern divisions hold for weeks. Japan declares war on Shanxi and the National Government and sends four divisions, a motorised unit and cavalry into Rehe.",
                "Вторжение в Жэхэ", "Японские войска и войска Маньчжоу-го вторгаются в Жэхэ. Армия Тан Юйлиня разваливается, и 4 марта небольшая моторизованная колонна без боя входит в Чэндэ; бои переходят на перевалы Великой стены, где дивизии Центральной армии и северян держатся неделями. Япония объявляет войну Шаньси и Национальному правительству и вводит в Жэхэ четыре дивизии, моторизованный отряд и кавалерию."),
 'JAPAN_TANGGU': ("The Tanggu Truce", "At Tanggu Chinese and Japanese officers sign a truce: a demilitarised zone south of the Great Wall, between Beiping and Tianjin and the passes, is left to Chinese police. Manchuria and Rehe are lost in all but name. Japan makes peace with Fengtian, the National Government, Shanxi and the Guominjun.",
                  "Тангуское перемирие", "В Тангу китайские и японские офицеры подписывают перемирие: демилитаризованная зона к югу от Великой стены, между Бэйпином, Тяньцзинем и перевалами, остаётся китайской полиции. Маньчжурия и Жэхэ потеряны во всём, кроме названия. Япония заключает мир с Фэнтянем, Национальным правительством, Шаньси и Гоминьцзюнем."),
 'JAPAN_HE_UMEZU': ("The He-Umezu Agreement", "Under Japanese pressure He Yingqin accepts General Umezu's demands: the Kuomintang's offices and Central Army troops leave Hebei, and Zhang Xueliang's 51st Army is moved out of the province. The National Government loses 300 gold; Fengtian loses two units around Beiping.",
                    "Соглашение Хэ-Умэдзу", "Под японским давлением Хэ Инцинь принимает требования генерала Умэдзу: отделения Гоминьдана и войска Центральной армии уходят из Хэбэя, а 51-я армия Чжан Сюэляна выводится из провинции. Национальное правительство теряет 300 золота; Фэнтянь теряет два отряда под Бэйпином."),
 'JAPAN_EAST_HEBEI': ("The East Hebei Autonomous Council", "At Tongzhou, east of Beiping, Yin Rugeng proclaims the East Hebei Anti-Communist Autonomous Council over twenty-two counties of the demilitarised zone, under Japanese protection. Students in Beiping march against the 'autonomy movement' in December.",
                      "Автономный совет Восточного Хэбэя", "В Тунчжоу, к востоку от Бэйпина, Инь Жугэн провозглашает Антикоммунистический автономный совет Восточного Хэбэя над двадцатью двумя уездами демилитаризованной зоны под японской защитой. В декабре студенты Бэйпина выходят на демонстрации против «движения за автономию»."),
 'JAPAN_MARCO_POLO': ("The Marco Polo Bridge", "Shots in the night at the Marco Polo Bridge near Wanping, during a Japanese exercise, become a battle and then a war. Within weeks Japan sends its armies into north China and Shanghai, and China, at last united against the invader, fights back. Japan declares war on every Chinese side; its China Garrison Army appears at Fengtai and the Kwantung Army reinforces Dairen.",
                      "Мост Марко Поло", "Ночные выстрелы у моста Марко Поло близ Ваньпина во время японских учений перерастают в бой, а затем в войну. Через несколько недель Япония вводит армии в северный Китай и в Шанхай, и Китай, наконец единый против захватчика, отвечает. Япония объявляет войну всем китайским сторонам; её Гарнизонная армия появляется у Фэнтая, Квантунская армия усиливает Дайрен."),
 'JAPAN_REINFORCE': ("The Kwantung Army reinforced", "Fresh Japanese troops arrive in Manchuria.", "Усиление Квантунской армии", "В Маньчжурию прибывают свежие японские войска."),
 # --- Guangxi
 'GX_HUNAN': ("The Hunan incident", "The Wuhan Political Council, run by the Guangxi clique, dismisses the governor of Hunan, Lu Diping, and sends troops to drive him out of Changsha without asking Nanjing. Guangxi raises two divisions at Yueyang.",
              "Хунаньский инцидент", "Уханьский политический совет, которым управляет гуансийская клика, снимает губернатора Хунани Лу Дипина и без согласия Нанкина посылает войска, чтобы изгнать его из Чанши. Гуанси получает две дивизии в Юэяне."),
 'GX_CHANGSHA': ("Guangxi marches north", "To join the war on Chiang, the Guangxi army and Zhang Fakui's troops march north through Hunan and take Changsha; they are beaten back at Hengyang by Guangdong's troops. Guangxi raises three divisions at Guilin.",
                 "Гуанси идёт на север", "Чтобы присоединиться к войне против Чана, гуансийская армия и войска Чжан Факуя идут на север через Хунань и берут Чаншу; у Хэнъяна их отбрасывают гуандунские войска. Гуанси получает три дивизии в Гуйлине."),
 'GX_CANTON_GOVT': ("The Canton government", "Opponents of Chiang Kai-shek, from Wang Jingwei and Sun Fo to Chen Jitang and the Guangxi leaders, set up a rival National Government in Canton. Guangxi receives 500 gold.",
                    "Кантонское правительство", "Противники Чан Кайши, от Ван Цзинвэя и Сунь Фо до Чэнь Цзитана и лидеров Гуанси, создают в Кантоне соперничающее Национальное правительство. Гуанси получает 500 золота."),
 'GX_THREE_SELFS': ("The Three Selfs", "Li Zongren, Bai Chongxi and Huang Xuchu rebuild Guangxi on self-defence, self-government and self-sufficiency: militia training for every able-bodied man, village schools, roads and provincial industry. Guangxi receives 300 gold and two militia units.",
                    "Три опоры на себя", "Ли Цзунжэнь, Бай Чунси и Хуан Сюйчу перестраивают Гуанси на началах самообороны, самоуправления и самообеспечения: военное обучение каждого трудоспособного мужчины, сельские школы, дороги и провинциальная промышленность. Гуанси получает 300 золота и два отряда ополчения."),
 'GX_LIANGGUANG': ("The Liangguang incident", "Guangdong and Guangxi announce that they will march north to resist Japan and mobilise their armies against Nanjing's policy. Within weeks Guangdong's generals and air force go over to Nanjing; Guangxi holds out until it reaches a settlement in September. Guangxi raises three divisions.",
                    "Инцидент Лянгуан", "Гуандун и Гуанси объявляют о походе на север для сопротивления Японии и мобилизуют армии против политики Нанкина. Через несколько недель генералы и авиация Гуандуна переходят к Нанкину; Гуанси держится до соглашения в сентябре. Гуанси получает три дивизии."),
 'GX_LEVY': ("Recruits for the Guangxi army", "New Guangxi troops are ready.", "Пополнение гуансийской армии", "Новые гуансийские войска готовы."),
 # --- the Communists
 'CCP_PENG': ("Peng Dehuai at Jinggangshan", "Peng Dehuai's Fifth Red Army, raised in the Pingjiang rising in July, reaches the Jinggang mountains and joins Mao Zedong and Zhu De. Two units of the Fifth Red Army arrive at Jinggangshan.",
              "Пэн Дэхуай в Цзинганшане", "Пятая Красная армия Пэн Дэхуая, поднятая в Пинцзянском восстании в июле, приходит в горы Цзинганшань и соединяется с Мао Цзэдуном и Чжу Дэ. Два отряда Пятой Красной армии прибывают в Цзинганшань."),
 'CCP_GANNAN': ("To southern Jiangxi", "Short of food and surrounded, the Fourth Red Army leaves the Jinggang mountains to Peng Dehuai and marches into southern Jiangxi and western Fujian, where the warlords' armies are thin. Two Red Army units appear near Ruijin.",
                "В Южную Цзянси", "Без продовольствия и в окружении Четвёртая Красная армия оставляет Цзинганшань Пэн Дэхуаю и уходит в Южную Цзянси и Западную Фуцзянь, где войска милитаристов редки. Два отряда Красной армии появляются у Жуйцзиня."),
 'CCP_CHANGTING': ("Changting", "The Fourth Red Army beats the local garrison and takes Changting in western Fujian, where it finds cloth, money and a uniform factory. The Communists receive 300 gold and a unit at Ruijin.",
                   "Чантин", "Четвёртая Красная армия разбивает местный гарнизон и берёт Чантин на западе Фуцзяни, где находит ткань, деньги и швейную фабрику. Коммунисты получают 300 золота и отряд у Жуйцзиня."),
 'CCP_GUTIAN': ("The Gutian conference", "At Gutian in western Fujian the Fourth Red Army's party conference adopts Mao's resolution on the party's command of the army and the army's political work among the people. The Communists receive a Great General.",
                "Конференция в Гутяни", "В Гутяни на западе Фуцзяни партийная конференция Четвёртой Красной армии принимает резолюцию Мао о руководстве партии армией и о политической работе армии среди населения. Коммунисты получают Великого полководца."),
 'CCP_CHANGSHA': ("Changsha", "On the party's orders to take the cities, Peng Dehuai's Third Red Army Group storms Changsha, the capital of Hunan, and holds it for some ten days before foreign gunboats and returning troops force it out. Two Red Army units appear near Changsha.",
                  "Чанша", "По приказу партии брать города Третья армейская группа Пэн Дэхуая штурмует Чаншу, столицу Хунани, и держит её около десяти дней, пока иностранные канонерки и вернувшиеся войска не вынуждают её уйти. Два отряда Красной армии появляются у Чанши."),
 'CCP_LONGGANG': ("Longgang", "Lured deep into the hills, Zhang Huizan's 18th Division is destroyed at Longgang and its commander captured; the first encirclement campaign falls apart. Two Red Army units and a captured battery appear near Ruijin.",
                  "Лунган", "Заманенная глубоко в горы 18-я дивизия Чжан Хуэйцзаня уничтожена у Лунгана, её командир взят в плен; первый поход окружения разваливается. Два отряда Красной армии и захваченная батарея появляются у Жуйцзиня."),
 'CCP_SOVIET_REPUBLIC': ("The Chinese Soviet Republic", "On the anniversary of the October Revolution the First National Soviet Congress proclaims the Chinese Soviet Republic at Ruijin, with Mao Zedong as chairman of its Central Executive Committee. The Communists receive 500 gold and two Red Army units near Ruijin.",
                         "Китайская Советская Республика", "В годовщину Октябрьской революции Первый всекитайский съезд Советов провозглашает в Жуйцзине Китайскую Советскую Республику во главе с Мао Цзэдуном как председателем её Центрального исполнительного комитета. Коммунисты получают 500 золота и два отряда Красной армии у Жуйцзиня."),
 'CCP_NINGDU': ("The Ningdu uprising", "The 26th Route Army, Feng Yuxiang's former soldiers sent to fight the Communists in Jiangxi, mutinies at Ningdu and goes over to the Red Army with its weapons. Three units and a machine-gun company of the Fifth Red Army Group appear near Ruijin.",
                "Нингдуское восстание", "26-я армия, бывшие солдаты Фэн Юйсяна, посланные воевать с коммунистами в Цзянси, восстаёт в Нинду и с оружием переходит к Красной армии. Три отряда и пулемётная рота Пятой армейской группы появляются у Жуйцзиня."),
 'CCP_LONG_MARCH': ("The Long March", "The fifth campaign's blockhouses close in. The Central Red Army and the party's leaders break out of the Jiangxi Soviet to the west, some eighty-six thousand people crossing the Yudu river with everything they can carry. Four units of the Central Red Army gather at Yudu.",
                    "Великий поход", "Блокгаузы пятого похода смыкаются. Центральная Красная армия и руководство партии прорываются из Цзянсийского советского района на запад: около восьмидесяти шести тысяч человек переходят реку Юйду со всем, что могут унести. Четыре отряда Центральной Красной армии собираются у Юйду."),
 'CCP_XIANG_RIVER': ("The Xiang River", "Crossing the Xiang river in northern Guangxi through the last line of blockhouses, the Central Red Army loses more than half its strength. The Communists lose two units of the Central Red Army.",
                     "Река Сянцзян", "Прорываясь через последнюю линию блокгаузов на реке Сянцзян на севере Гуанси, Центральная Красная армия теряет больше половины своего состава. Коммунисты теряют два отряда Центральной Красной армии."),
 'CCP_ZUNYI': ("The Zunyi conference", "In Zunyi, taken in January, an enlarged meeting of the Politburo condemns the military line of the Comintern's adviser and its supporters and brings Mao Zedong back into the leadership of the army. The Communists receive a Great General near Zunyi.",
               "Совещание в Цзуньи", "В Цзуньи, взятом в январе, расширенное совещание Политбюро осуждает военную линию советника Коминтерна и его сторонников и возвращает Мао Цзэдуна в руководство армией. Коммунисты получают Великого полководца у Цзуньи."),
 'CCP_LUDING': ("The Luding Bridge", "After a forced march along the Dadu river, a vanguard of the Red Army crosses the chain bridge at Luding under fire and opens the way north. A Red Army vanguard appears at Luding.",
                "Мост Лудин", "После форсированного марша вдоль реки Даду авангард Красной армии под огнём переходит цепной мост у Лудина и открывает путь на север. Авангард Красной армии появляется у Лудина."),
 'CCP_SHAANBEI': ("Northern Shaanxi", "A year after leaving Jiangxi, the column led by Mao Zedong reaches Wuqi in northern Shaanxi, where the soviet base of Liu Zhidan and Gao Gang receives it. Two units of the Shaanbei Red Army appear at Wuqi.",
                  "Северная Шэньси", "Через год после ухода из Цзянси колонна во главе с Мао Цзэдуном приходит в Уци на севере Шэньси, где её принимает советский район Лю Чжиданя и Гао Гана. Два отряда Шэньбэйской Красной армии появляются в Уци."),
 'CCP_WAYAOBAO': ("Wayaobao", "The Central Committee settles at Wayaobao, which becomes the seat of the Communist leadership in the northwest. If the land is free, the Communists found the city of Wayaobao and receive a unit of Red Guards there.",
                  "Ваяобао", "ЦК обосновывается в Ваяобао, которое становится резиденцией коммунистического руководства на северо-западе. Если земля свободна, коммунисты основывают город Ваяобао и получают там отряд Красной гвардии."),
 'CCP_EASTERN_EXPEDITION': ("The Eastern Expedition", "The Red Army crosses the Yellow River into Shanxi to recruit, collect supplies and open a road towards the Japanese in Hebei; Nanjing sends divisions to help Yan Xishan. Three Red Army units cross the Yellow River into Shanxi; the National Government sends two divisions into Shanxi.",
                            "Восточный поход", "Красная армия переходит Хуанхэ в Шаньси, чтобы набрать бойцов, собрать припасы и открыть дорогу к японцам в Хэбэе; Нанкин посылает дивизии на помощь Янь Сишаню. Три отряда Красной армии переходят Хуанхэ в Шаньси; Национальное правительство посылает в Шаньси две дивизии."),
 'CCP_HUINING': ("The armies reunited", "In Gansu the Fourth Front Army of Zhang Guotao and Xu Xiangqian and then the Second Front Army of He Long join the First Front Army: the Long March is over. Two units each of the Second and Fourth Front Armies appear at Huining.",
                 "Армии соединились", "В Ганьсу Четвёртый фронт Чжан Готао и Сюй Сянцяня, а затем Второй фронт Хэ Луна соединяются с Первым фронтом: Великий поход окончен. Отряды Второго и Четвёртого фронтов появляются в Хуэйнине."),
 'CCP_LEVY': ("Red Guards", "Villagers of the base area join the Red Guards.", "Красная гвардия", "Крестьяне опорной базы вступают в Красную гвардию."),
 # --- bandits and rebels
 'BARB_FUJIAN': ("The Fujian People's Government", "In Fuzhou the 19th Route Army, the defenders of Shanghai, and the politicians around Li Jishen and Chen Mingshu proclaim a People's Revolutionary Government of the Republic of China against Chiang Kai-shek. Nanjing turns divisions from the Jiangxi front against them. Units of the People's Revolutionary Army appear at Fuzhou; the National Government raises three divisions.",
                 "Фуцзяньское народное правительство", "В Фучжоу 19-я армия, защитница Шанхая, и политики вокруг Ли Цзишэня и Чэнь Миншу провозглашают Народно-революционное правительство Китайской Республики против Чан Кайши. Нанкин поворачивает против них дивизии с цзянсийского фронта. Отряды Народно-революционной армии появляются у Фучжоу; Национальное правительство получает три дивизии."),
 'BARB_SUIYUAN': ("The Suiyuan campaign", "Prince De's Inner Mongolian army and the Grand Han Righteous Army, armed and advised by the Kwantung Army, attack eastern Suiyuan. Mongol and puppet units appear north of Guisui.",
                  "Суйюаньская кампания", "Внутреннемонгольская армия князя Дэ и Великая ханьская справедливая армия, вооружённые Квантунской армией и с её советниками, наступают на восточный Суйюань. Монгольские и марионеточные отряды появляются к северу от Гуйсуя."),
 'BARB_HENAN': ("Bandits in Henan", "A bandit army raids the towns of western Henan.", "Разбойники в Хэнани", "Разбойничья армия грабит города западной Хэнани."),
 'BARB_SHANDONG': ("The Red Spears", "The Red Spear society, peasants who believe their charms make them proof against bullets, rises against tax collectors and soldiers.", "Красные пики", "Общество Красных пик, крестьяне, верящие, что заговоры делают их неуязвимыми для пуль, поднимается против сборщиков налогов и солдат."),
 'BARB_HONGHUZI': ("Honghuzi", "Mounted bandits, the honghuzi, raid the railway towns of northern Manchuria.", "Хунхузы", "Конные разбойники, хунхузы, нападают на железнодорожные города северной Маньчжурии."),
 'BARB_SOUTH': ("Hill bandits", "Bandits come down from the hills of the south.", "Горные разбойники", "Разбойники спускаются с южных гор."),
}
